  ('P4','huanlehuoban-2025',4,'今天我值日',12,'劝告','quàn gào','urge; advise','read',false,'希望人改正错误或接受意见而说的话。','经过大家的劝告，他终于肯戒掉抽烟的恶习。','明明知道自己犯了错误，你为什么不接受朋友的劝告？',null,null,null,null),
